//! Whole original procedure-policy oracle through one checked diagnostic owner.
use std::{path::Path,sync::Arc,io::Write};
#[path="../../dm-analysis/examples/support/acquired_files.rs"]mod acquired_files;
#[path="../../dm-analysis/examples/support/reference_hierarchy.rs"]mod reference_hierarchy;
fn failure(error:dm_analysis::policy_body_demand::PolicyFailure)->Box<dyn std::error::Error>{match error{dm_analysis::policy_body_demand::PolicyFailure::Operational(actual)=>Box::new(actual),dm_analysis::policy_body_demand::PolicyFailure::Unsupported(message)=>message.0.into()}}
fn emit(output:&mut impl Write,finding:dm_analysis::checks_proc_visibility::Finding<'_>,severity:dm_analysis::check_policy::DiagnosticSeverity,project:&Path)->Result<(),Box<dyn std::error::Error>>{use dm_analysis::check_policy::DiagnosticSeverity as S;let row=finding.diagnostic();let point=finding.reported_point()?;let(key,line,column)=point.coordinates();let synthetic=project.parent().ok_or("project parent absent")?.join(key);let path=if finding.is_parser_synthetic(){synthetic.as_path()}else{key};serde_json::to_writer(&mut *output,&serde_json::json!({"family":row.family,"severity":match severity{S::Error=>"error",S::Warning=>"warning",S::Info=>"info",S::Hint=>"hint"},"file":path,"line":line,"expanded_column":column,"message":row.message,"notes":row.notes.iter().map(|note|note.legacy_text()).collect::<Vec<_>>()}))?;output.write_all(b"\n")?;Ok(())}
fn main()->Result<(),Box<dyn std::error::Error>>{
 use dm_analysis::{checks_proc_visibility::Family,check_policy::{DiagnosticSeverity as S,cli_printed}};let project=std::env::args().nth(1).ok_or("expected project")?;let family=match std::env::args().nth(2).as_deref(){Some("private_proc")=>Family::Private,Some("protected_proc")=>Family::Protected,Some("must_call_parent")=>Family::MustCallParent,Some("must_not_override")=>Family::MustNotOverride,Some("redefined_proc")=>Family::Redefined,_=>return Err("expected original procedure family".into())};let project=Path::new(&project);if !project.is_absolute(){return Err("project must be caller-absolute".into())}
 let files=acquired_files::AcquiredFiles::default();let seed=reference_hierarchy::seed();let db=Arc::new(dmbc::query_db::QueryDb::default());let host:Arc<dyn dm_tree::frontend::SettingExpressionQueries>=db.clone();let executor=dm_exec::BuildExecutor::new(1)?;let front=dm_tree::frontend::build_for_checker_diagnostics_with_state_checked(project,&files,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None},None,&executor,None,&host).map_err(|e|format!("native procedure diagnostic frontend: {e:?}"))?.with_body_queries(db.clone())?;let view=front.source_view()?;let archive=view.archive();let tree=archive.tree();let profile=tree.checker_builtin_profile().ok_or("actual checker profile absent")?;
 let selected=dm_analysis::check_configuration::select(project,None);let bytes=match std::fs::read(&selected.path){Ok(bytes)=>Some(bytes),Err(actual)if actual.kind()==std::io::ErrorKind::NotFound=>None,Err(actual)=>return Err(actual.into())};let loaded=dm_analysis::check_configuration::load(&selected,dm_analysis::check_configuration::Capture{path:&selected.path,read:match &bytes{Some(bytes)=>dm_analysis::check_configuration::CapturedRead::Bytes(bytes),None=>dm_analysis::check_configuration::CapturedRead::AutodetectAbsent}})?;let mut output=std::io::stdout().lock();
 // Original parser diagnostics precede checker body diagnostics. The projection
 // reports only genuine same-owner formal duplicates, never native-only errors.
 if family==Family::Redefined{for ordinal in 0..archive.len(){for finding in dm_analysis::checks_proc_visibility::declaration_redeclaration_checked(archive,ordinal,view.receipt(),&||Ok(())).map_err(failure)?.iter(){let default=finding.original_fixed_level().ok_or("original declaration producer severity absent")?;if let Some(level)=loaded.policy.register(finding.registration_tag(),default){if cli_printed(level){emit(&mut output,finding,level,project)?;}}}}}
 let producer=if family==Family::Redefined{S::Hint}else{S::Error};if let Some(level)=loaded.policy.register(Some(family.name()),producer){if cli_printed(level){for(ordinal,_)in dm_analysis::checker_order::archived_bodies(archive)?{let body=archive.parse_checked(ordinal).map_err(|failure|match failure{dm_tree::frontend::BodySyntaxFailure::Operational(actual)=>Box::new(actual)as Box<dyn std::error::Error>,dm_tree::frontend::BodySyntaxFailure::Syntax(error)=>error.message.into()})?;for finding in dm_analysis::checks_proc_visibility::archived_checked(archive,&body,tree,profile,family,if family==Family::Redefined{dm_analysis::checks::Severity::Warning}else{dm_analysis::checks::Severity::Error},&||Ok(())).map_err(failure)?.iter(){emit(&mut output,finding,level,project)?;}}}}
 Ok(())
}
